macro_rules! abi_table {
    ($( $name:ident = $val:literal ),+ $(,)?) => {
        $( pub const $name: usize = $val; )+
        pub const ABI_NAMES: &[&str] = &[ $( stringify!($name) ),+ ];
        pub const ABI_VALUES: &[usize] = &[ $( $val ),+ ];
    };
}
