const fn fnv1a(b: &[u8]) -> u64 {
    let mut h = 0xcbf29ce484222325u64;
    let mut i = 0;
    while i < b.len() { h ^= b[i] as u64; h = h.wrapping_mul(0x100000001b3); i += 1; }
    h
}
